  let state={projects:[],runs:[],queue:[],current:null,paused:false,resources:[],issues:[],templates:[],environments:[]};
  let view='dashboard',selectedRun=null,detail=null,detailTab='stages',projectFilter='',search='',runFilter='',lastRefresh=null,connectionError='',loading=true,busy=false;
  let sidebarCollapsed=false;
  try{sidebarCollapsed=root.localStorage?.getItem('pwb.sidebar-collapsed')==='1';}catch{}
  const selectedCandidates=new Set(),logCache=new Map(),exportLinks=new Map();let molecularViewers=[],viewerEpoch=0,libraryPromise=null,viewerBinding=null;const demo=!!root.PWB_DEMO_STATE;
  if(demo)state=JSON.parse(JSON.stringify(root.PWB_DEMO_STATE));
