  const templates=()=>{const all=asList(state.templates).map(t=>({...t,fields:asList(t.fields).map(f=>({...f}))}));for(const t of genericTemplates)if(!all.some(x=>x.id===t.id))all.push(t);const script=all.find(t=>t.id==='generic_script');if(script&&!script.fields.some(f=>f.name==='argv'))script.fields.push(genericTemplates[0].fields[0]);return all;};
